define({"topics":[{"title":"Preparing the patient table for replacing the actuator","shortdesc":"<p class=\"shortdesc\">Prepares the patient table for removing the actuator. The patient table is raised electro-mechanically or manually and the table is removed from the magnet room.<\/p>","href":"t_PreparingThePatientTableForReplacingTheActuator.html","attributes":{"data-id":"id_2003050"},"menu":{"hasChildren":false},"tocID":"id_2003050-d46e419097","topics":[]},{"title":"Removing the patient table","shortdesc":"<p class=\"shortdesc\">Disconnects and removes the patient table from the magnet.<\/p>","href":"t_RemovingThePatientTableParent_2.html","attributes":{"data-id":"id_2003453"},"menu":{"hasChildren":true},"tocID":"id_2003453-d46e419202","next":"id_2003453-d46e419202"},{"title":"Replacing the actuator","shortdesc":"<p class=\"shortdesc\">Replaces either the EHA or SKF table up or down actuator.<\/p>","href":"t_ReplacingTheActuatorParent.html","attributes":{"data-id":"id_2013527"},"menu":{"hasChildren":true},"tocID":"id_2013527-d46e420659","next":"id_2013527-d46e420659"},{"title":"Installing the patient table","shortdesc":"<p class=\"shortdesc\">Installs the patient table and connects it to the magnet.<\/p>","href":"t_InstallingThePatientTableParent.html","attributes":{"data-id":"id_2003454"},"menu":{"hasChildren":true},"tocID":"id_2003454-d46e421396","next":"id_2003454-d46e421396"},{"title":"Finalizing replacing the actuator","shortdesc":"<p class=\"shortdesc\">Performs preliminary checks and prepares the patient table to be restored to normal operating condition.<\/p>","href":"t_FinalizingReplacingTheElectro-hydraulicActuator.html","attributes":{"data-id":"id_2004428"},"menu":{"hasChildren":false},"tocID":"id_2004428-d46e423686","topics":[]},{"title":"Checking the patient table","shortdesc":"<p class=\"shortdesc\">Makes sure the following systems operate correctly: patient table up and down, cradle in and out, emergency egress, and touch-and-go strip.<\/p>","href":"t_CheckingThePatientTable_6.html","attributes":{"data-id":"id_2003244"},"menu":{"hasChildren":true},"tocID":"id_2003244-d46e423791","next":"id_2003244-d46e423791"},{"title":"Doing a check scan","shortdesc":"<p class=\"shortdesc\"> A check scan is done at the conclusion of many procedures. This functional check assures the unit is in good clinical working order.<\/p>","href":"t_DoingACheckScan_139.html","attributes":{"data-id":"id_2001754"},"menu":{"hasChildren":false},"tocID":"id_2001754-d46e424415","topics":[]}]});